import java.io.*;
import java.nio.ByteBuffer;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicReference;
import javax.websocket.*;
import javax.websocket.server.ServerEndpoint;

@ServerEndpoint("/upload")
public class UploadEndpoint {

    private final AtomicReference<ProcessingContext> contextRef = new AtomicReference<>();
    private final ExecutorService processorPool = Executors.newFixedThreadPool(4);
    private volatile Session wsSession;

    static class ProcessingContext {
        byte[] buffer;
        int offset;
        String clientId;
        CompletableFuture<byte[]> pendingResult;

        ProcessingContext(String clientId, int size) {
            this.buffer = new byte[size];
            this.offset = 0;
            this.clientId = clientId;
            this.pendingResult = new CompletableFuture<>();
        }

        void appendChunk(byte[] chunk, int len) {
            System.arraycopy(chunk, 0, buffer, offset, len);
            offset += len;
        }

        void release() {
            buffer = null;
            offset = 0;
            pendingResult = null;
        }
    }

    @OnOpen
    public void onOpen(Session session) {
        this.wsSession = session;
        session.setMaxBinaryMessageBufferSize(1024 * 1024);
    }

    @OnMessage
    public void onMessage(ByteBuffer message, Session session) throws IOException {
        byte[] data = new byte[message.remaining()];
        message.get(data);

        if (data.length >= 4 && new String(data, 0, 4).equals("INIT")) {
            handleInit(data, session);
        } else if (data.length >= 4 && new String(data, 0, 4).equals("CHNK")) {
            handleChunk(data, session);
        } else if (data.length >= 4 && new String(data, 0, 4).equals("DONE")) {
            handleDone(session);
        } else if (data.length >= 4 && new String(data, 0, 4).equals("CNCL")) {
            handleCancel(session);
        }
    }

    private void handleInit(byte[] data, Session session) throws IOException {
        int size = ByteBuffer.wrap(data, 4, 4).getInt();
        if (size <= 0 || size > 10 * 1024 * 1024) {
            session.getBasicRemote().sendText("ERROR: invalid size");
            return;
        }
        String clientId = session.getId();
        ProcessingContext ctx = new ProcessingContext(clientId, size);
        contextRef.set(ctx);
        session.getBasicRemote().sendText("READY");
    }

    private void handleChunk(byte[] data, Session session) throws IOException {
        ProcessingContext ctx = contextRef.get();
        if (ctx == null) {
            session.getBasicRemote().sendText("ERROR: no context");
            return;
        }
        int chunkLen = data.length - 4;
        if (ctx.offset + chunkLen > ctx.buffer.length) {
            session.getBasicRemote().sendText("ERROR: overflow");
            return;
        }
        ctx.appendChunk(java.util.Arrays.copyOfRange(data, 4, data.length), chunkLen);
    }

    private void handleDone(Session session) throws IOException {
        ProcessingContext ctx = contextRef.get();
        if (ctx == null) {
            session.getBasicRemote().sendText("ERROR: no context");
            return;
        }

        // Capture reference for async callback
        final ProcessingContext capturedCtx = ctx;

        processorPool.submit(() -> {
            try {
                // Simulate processing delay
                Thread.sleep(100);
                byte[] result = processUpload(capturedCtx);
                capturedCtx.pendingResult.complete(result);
            } catch (Exception e) {
                capturedCtx.pendingResult.completeExceptionally(e);
            }
        });

        // Register completion callback using captured context
        ctx.pendingResult.thenAccept(result -> {
            try {
                sendResult(capturedCtx, result);
            } catch (IOException e) {
                e.printStackTrace();
            }
        });
    }

    private void handleCancel(Session session) throws IOException {
        ProcessingContext ctx = contextRef.getAndSet(null);
        if (ctx != null) {
            // Release resources immediately
            ctx.release();
            session.getBasicRemote().sendText("CANCELLED");
        }
    }

    private byte[] processUpload(ProcessingContext ctx) {
        // Access buffer after potential release - dangling reference
        byte[] snapshot = ctx.buffer;
        if (snapshot == null) {
            return new byte[0];
        }
        // Simulate hash computation
        int hash = 0;
        for (int i = 0; i < ctx.offset; i++) {
            hash = hash * 31 + snapshot[i];
        }
        return ByteBuffer.allocate(4).putInt(hash).array();
    }

    private void sendResult(ProcessingContext ctx, byte[] result) throws IOException {
        // Use ctx.clientId after potential release - dangling reference to freed context
        // ctx.buffer is null but ctx.clientId may still reference stale session data
        if (wsSession != null && wsSession.isOpen()) {
            String response = "RESULT:" + ctx.clientId + ":" +
                ByteBuffer.wrap(result).getInt();
            wsSession.getBasicRemote().sendText(response);
        }
    }

    @OnClose
    public void onClose(Session session) {
        ProcessingContext ctx = contextRef.getAndSet(null);
        if (ctx != null) {
            ctx.release();
        }
        processorPool.shutdown();
    }

    @OnError
    public void onError(Session session, Throwable throwable) {
        ProcessingContext ctx = contextRef.getAndSet(null);
        if (ctx != null) {
            ctx.release();
        }
    }
}
